const DUNGEON_ZONE_ALIASES = {1584: [1584, 1585]};   /* QuestieDB keys Blackrock Depths NPCs on 1585 */
function dungeonZones(zone) { return DUNGEON_ZONE_ALIASES[zone] || [zone]; }
function questieDungeonSections(d) {
  const zones = dungeonZones(d.zone);
  const npcs = Object.keys(QDB.npcs).filter(id => zones.includes(QDB.npcs[id].zone)).map(id => [id, QDB.npcs[id]]).sort((a, b) => (b[1].rank || 0) - (a[1].rank || 0) || (b[1].lmax || 0) - (a[1].lmax || 0) || a[1].n.localeCompare(b[1].n));
  if (!npcs.length) return '';
  const rows = npcs.map(([id, n]) => `<tr><td>${npcLink(id)}${n.sub ? ` <span class="muted small">&lt;${esc(n.sub)}&gt;</span>` : ''}</td><td class="num">${n.lmin ? (n.lmin === n.lmax ? n.lmin : n.lmin + '–' + n.lmax) : ''}</td><td>${RANK[n.rank] || ''}</td>
    <td class="small">${(n.drops || []).slice(0, 8).map(i => itemLinkAny(i, {noicon: true})).join(', ')}${(n.drops || []).length > 8 ? `, <a href="#/npc/${id}">+${n.drops.length - 8} more</a>` : ''}</td></tr>`);
  return `<h2>NPCs <span class="muted small">${npcs.length}, from QuestieDB</span></h2><table><thead><tr><th>NPC</th><th>Level</th><th>Rank</th><th>Notable drops</th></tr></thead><tbody>${rows.join('')}</tbody></table>`;
}

/* ---------------------------------------------------------------- dungeon prep: what to hold before the first run, and the earliest level it can happen */
function dungeonPackage(d, side) {
  const own = d.quests.filter(q => questSideOk(q, side));
  const pkg = own.map(q => ({id: q.id, n: q.n, rl: Math.max(q.rl || 0, (QDB.quests[q.id] || {}).rl || 0), lv: q.lv}));
  const pre = new Map();   // prerequisite id -> {rl, zone, start, needs:[dungeon quest ids], oneOf}
  const seen = new Set(own.map(q => q.id));
  const walk = (id, root, oneOf) => {
    const qq = QDB.quests[id];
    const preds = [];
    if (qq) {
      (qq.preg || []).forEach(p => preds.push([p, false]));
      (qq.pre || []).forEach(p => preds.push([p, (qq.pre || []).length > 1]));
      if (qq.parent) preds.push([qq.parent, false]);
    }
    const wq = Object.values(QUESTS.dungeons).flatMap(x => x.quests).find(x => x.id === id);
    if (wq && wq.chain) {   // Wowhead series: everything before this quest's step
      const pos = wq.chain.findIndex(s => s[1].some(x => x[0] === id));
      wq.chain.slice(0, Math.max(pos, 0)).forEach(s => s[1].forEach(x => preds.push([x[0], s[1].length > 1])));
    }
    preds.forEach(([p, one]) => {
      if (seen.has(p)) { if (pre.has(p) && !pre.get(p).needs.includes(root)) pre.get(p).needs.push(root); return; }
      seen.add(p);
      const pq = QDB.quests[p];
      const w = Object.values(QUESTS.dungeons).flatMap(x => x.quests).find(x => x.id === p);
      pre.set(p, {id: p, n: pq ? pq.n : (w ? w.n : '#' + p), rl: Math.max(pq ? pq.rl || 0 : 0, w ? w.rl || 0 : 0), lv: pq ? pq.lv : (w ? w.lv : 0), zone: pq ? pq.zone : null,
        start: pq ? pq.start : null, needs: [root], oneOf: one || oneOf, side: pq ? questSide(pq) : ''});
      walk(p, root, one || oneOf);
    });
  };
  own.forEach(q => walk(q.id, q.id, false));
  const gate = pkg.length ? Math.max(...pkg.map(q => q.rl)) : 0;
  const preMax = pre.size ? Math.max(...[...pre.values()].filter(p => !p.oneOf).map(p => p.rl), 0) : 0;
  return {pkg, pre: [...pre.values()].sort((a, b) => a.rl - b.rl || (a.zone || 0) - (b.zone || 0) || a.n.localeCompare(b.n)), gate, ready: Math.max(gate, preMax)};
}
function prepSection(d, side) {
  const p = dungeonPackage(d, side);
  if (!p.pkg.length) return '';
  const qname = id => { const q = p.pkg.find(x => x.id === id); return q ? esc(q.n) : '#' + id; };
  const mobs = Object.values(QDB.npcs).filter(n => dungeonZones(d.zone).includes(n.zone) && n.lmin && !n.friendly);
  const mobLv = mobs.length ? `${Math.min(...mobs.map(n => n.lmin))}–${Math.max(...mobs.map(n => n.lmax || n.lmin))}` : '';
  let h = `<h2>Prep <span class="muted small">run once, as soon as the group can hold every quest</span></h2>
  <div class="tiles"><div class="tile"><div><b>${p.ready}</b><div class="sub">ready at level: every quest and prerequisite obtainable</div></div></div><div class="tile"><div><b>${p.gate}</b><div class="sub">highest required level among the dungeon's ${p.pkg.length} quests</div></div></div><div class="tile"><div><b>${p.pre.length}</b><div class="sub">prerequisite quests to finish first</div></div></div>${mobLv ? `<div class="tile"><div><b>${mobLv}</b><div class="sub">mob levels inside (QuestieDB)</div></div></div>` : ''}</div>`;
  if (p.pre.length) {
    h += `<table><thead><tr><th>Prerequisite</th><th>Req</th><th>Level</th><th>Zone</th><th>Start</th><th>Needed for</th></tr></thead><tbody>${p.pre.map(x => `<tr><td>${questLink(x.id)}${x.oneOf ? ' <span class="muted small">one of</span>' : ''}${x.side && x.side !== 'Both' ? ` <span class="muted small">${x.side}</span>` : ''}</td><td class="num">${x.rl || ''}</td><td class="num">${x.lv || ''}</td><td>${zoneLink(x.zone)}</td><td class="small">${x.start ? [...(x.start.c || []).map(npcLink), ...(x.start.i || []).map(i => itemLinkAny(i, {noicon: true}))].join(', ') : ''}</td><td class="small">${x.needs.map(qname).join(', ')}</td></tr>`).join('')}</tbody></table>`;
  } else h += '<p class="muted">No prerequisites: every quest is available directly.</p>';
  const late = p.pkg.filter(q => q.rl === p.gate);
  if (late.length && p.gate) h += `<p class="muted small">Level ${p.gate} is set by: ${late.map(q => esc(q.n)).join(', ')}.</p>`;
  return h;
}


const PATCHES = window.FR_PATCHES || [];
const FIELD_NAMES = {n: 'name', q: 'quality', il: 'item level', rl: 'required level', b: 'binding', mc: 'unique', st: 'stack', sp: 'sell price',
  cs: 'bag slots', ac: 'classes', rs: 'required skill', s: 'stats', ar: 'armor', dm: 'damage', fx: 'effects', set: 'set', c: 'class', sc: 'subclass',
  it: 'slot', d: 'description', ad: 'aura text', r: 'rank', lv: 'level', pw: 'cost', ct: 'cast time', cd: 'cooldown', rg_: 'reagents', rg: 'reagents',
  cr: 'creates', en: 'enchant', tb: 'taught by', lo: 'yellow at', hi: 'grey at', req: 'requires skill', cat: 'category', sl: 'profession'};
function fmtVal(k, v) {
  if (v == null) return '<span class="muted">none</span>';
  if (k === 's') return v.map(x => `${x[1] >= 0 ? '+' : ''}${x[1]} ${STAT_LABEL[x[0]] || M.stats[x[0]] || x[0]}`).join(', ');
  if (k === 'dm') return v.min != null ? `${v.min}-${v.max} (${v.speed}s, ${v.dps} dps)` : `${v.dps} dps`;
  if (k === 'rg_' || k === 'rg') return v.map(x => `${ITEMS[x[0]] ? ITEMS[x[0]].n : '#' + x[0]}${x[1] > 1 ? ' ×' + x[1] : ''}`).join(', ');
  if (k === 'cr') return `${ITEMS[v[0]] ? ITEMS[v[0]].n : '#' + v[0]}${v[1] > 1 ? ' ×' + v[1] : ''}`;
  if (k === 'fx') return v.map(x => `${TRIG[x[0]] || x[0]}: ${SPELLS[x[1]] ? SPELLS[x[1]].n : '#' + x[1]}`).join('; ');
  if (k === 'tb') return v.map(x => ITEMS[x] ? ITEMS[x].n : '#' + x).join(', ');
  if (k === 'sp') return money(v);
  if (k === 'sl') return M.skillLines[v] || v;
  if (k === 'ac') return classList(v);
  if (typeof v === 'object') return esc(JSON.stringify(v));
  return esc(String(v));
}
function patchSection(title, sec, link) {
  const lim = 250;
  const list = (arr, fn) => `<ul>${arr.slice(0, lim).map(fn).join('')}${arr.length > lim ? `<li class="muted">…and ${arr.length - lim} more</li>` : ''}</ul>`;
  let h = `<h3>${title} <span class="muted small">+${sec.added.length} / −${sec.removed.length} / ~${sec.changed.length}</span></h3>`;
  if (!sec.added.length && !sec.removed.length && !sec.changed.length) return h + '<p class="muted">No changes.</p>';
  if (sec.added.length) h += '<h4>Added</h4>' + list(sec.added, a => `<li>${link(a[0], a[1])}</li>`);
  if (sec.removed.length) h += '<h4>Removed</h4>' + list(sec.removed, a => `<li>${esc(a[1])} <span class="muted small">#${a[0]}</span></li>`);
  if (sec.changed.length) h += '<h4>Changed</h4>' + list(sec.changed, a => `<li>${link(a[0], a[1])}<div class="small chg">${Object.entries(a[2]).map(([k, v]) => `${FIELD_NAMES[k] || k}: ${fmtVal(k, v[0])} → ${fmtVal(k, v[1])}`).join('<br>')}</div></li>`);
  return h;
}
function pagePatches(params) {
  if (!PATCHES.length) return `<h1>Patches</h1><p class="muted">Only one build snapshot so far (${M.build}). Diffs appear here once a second Forever build has been snapshotted.</p>`;
  const cur = params.to ? PATCHES.find(p => p.to === params.to) : PATCHES[0];
  const itemLk = (id, n) => ITEMS[id] ? itemLink(id) : esc(n) + ` <span class="muted small">#${id}</span>`;
  const spellLk = (id, n) => SPELLS[id] ? spellLink(id, {rank: true}) : esc(n) + ` <span class="muted small">#${id}</span>`;
  return `<h1>Patches</h1><p class="muted">Client data diffs between consecutive Forever builds snapshotted by the build script. Builds: ${M.builds.join(' → ')}.</p>
  <div class="tabs">${PATCHES.map(p => `<a href="#/patches?to=${p.to}" class="${p === cur ? 'on' : ''}">${p.from} → ${p.to}</a>`).join('')}</div>
  <h2>${cur.from} → ${cur.to} <span class="muted small">snapshotted ${cur.date}</span></h2>
  <div class="row"><div class="col">${patchSection('Recipes', cur.recipes, spellLk)}${patchSection('Items', cur.items, itemLk)}</div><div class="col">${patchSection('Spells', cur.spells, spellLk)}</div></div>`;
}

function pageSearch(params) {
  const q = params.q || '';
  const r = search(q, 300);
  return `<h1>Search: ${esc(q)}</h1>${r.length ? `<ul>${r.map(e => `<li>${resultLink(e)} <span class="muted small">${e.t}</span></li>`).join('')}</ul>` : '<p class="muted">No matches.</p>'}`;
}

/* ---------------------------------------------------------------- router */
function parseHash() {
  const h = location.hash.replace(/^#\/?/, '');
  const [path, qs] = h.split('?');
  const params = {};
  (qs || '').split('&').forEach(kv => { if (!kv) return; const [k, v] = kv.split('='); params[decodeURIComponent(k)] = decodeURIComponent(v || ''); });
  return {parts: path.split('/').filter(Boolean), params};
}
let lastPath = '';
function render() {
  const {parts, params} = parseHash();
  const [p, id] = parts;
  const path = parts.join('/');
  if (p === 'items' && params.flag && path !== lastPath) { STATE.items = {q: '', c: '', sc: '', qmin: '', lmin: '', lmax: '', flag: params.flag}; }
  if (p === 'profession' && path !== lastPath) { STATE.prof = {q: '', skill: STATE.prof.skill, flag: params.new ? 'new' : '', hideGrey: false, view: params.view || STATE.prof.view || 'recipes', bop: true, slot: '', lmax: ''}; }
  let html;
  switch (p) {
    case undefined: html = pageHome(); break;
    case 'professions': html = pageProfessions(); break;
    case 'profession': html = pageProfession(id, params); break;
    case 'item': html = pageItem(id); break;
    case 'items': html = pageItems(); break;
    case 'spell': html = pageSpell(id); break;
    case 'classes': html = pageClasses(); break;
    case 'class': html = pageClass(id); break;
    case 'line': html = pageLine(id); break;
    case 'sets': html = pageSets(); break;
    case 'set': html = pageSet(id); break;
    case 'zones': html = pageZones(); break;
    case 'zone': html = pageZone(id); break;
    case 'new': html = pageNew(); break;
    case 'search': html = pageSearch(params); break;
    case 'patches': html = pagePatches(params); break;
    case 'bop': html = pageBop(); break;
    case 'dungeons': html = pageDungeons(); break;
    case 'collected': html = pageCollected(); break;
    case 'quest': html = pageQuest(id); break;
    case 'npc': html = pageNpc(id); break;
    case 'dungeon': html = pageDungeon(id, params); break;
    case 'prep': html = pagePrep(id); break;
    case 'maps': html = pageMaps(); break;
    case 'map': html = pageMap(id); break;
    default: html = '<h1>Not found</h1>';
  }
  $('#main').innerHTML = html;
  if (p === 'profession') bindProfession();
  if (p === 'items') bindItems();
  if (p === 'class') bindClass();
  if (p === 'bop') bindBop();
  if (p === 'zone') bindDungeon();
  if (p === 'dungeons' || p === 'dungeon') { bindDungeon(); if (p === 'dungeon' && path !== lastPath) STATE.dq.q = ''; const hlRow = params.hl && document.getElementById('q' + params.hl); if (hlRow) setTimeout(() => hlRow.scrollIntoView({block: 'center'}), 0); }
  if (path !== lastPath) { window.scrollTo(0, 0); lastPath = path; }
  $('#tip').hidden = true;
  const h1 = $('#main h1');
  const t = h1 ? [...h1.childNodes].filter(n => !(n.classList && n.classList.contains('badge'))).map(n => n.textContent).join('').trim() : '';
  document.title = (t ? t + ' – ' : '') + 'Forever Ref';
}
window.addEventListener('hashchange', render);
